"""SQLite-specific declarative reasoning, fixtures, and safe changes."""
from build import S, lesson as L

def sql():
 return [
 L('null-logic','Three-valued logic and conditional expressions',
 'SQL predicates can be true, false, or unknown. NULL means a missing value, so equality to NULL is unknown; use IS NULL to test absence. WHERE keeps only true rows. COALESCE chooses the first non-null value, while NULLIF can turn a sentinel into NULL. A CHECK constraint rejects false but permits unknown in SQLite, so add NOT NULL when absence must also be rejected. Do not translate Python truthiness into SQL filtering rules.',
 S('SELECT ~COALESCE~(NULL,${n},${m});','${n}','NULL|${m}','COALESCE returns the first non-null argument.','MAX|MIN'),
 S('SELECT ~NULLIF~(${n},${n});','NULL','${n}|0','Equal arguments make NULLIF return NULL.','COALESCE|MAX'),
 S('SELECT CASE WHEN NULL=NULL THEN \'equal\' ~ELSE \'unknown\'~ END;','unknown','equal|NULL','NULL=NULL is unknown, so CASE does not take the true branch.','ELSE \'equal\'|'),
 S('CREATE TABLE item(n INTEGER CHECK(n>0)); INSERT INTO item VALUES(NULL); SELECT ~COUNT(*)~ FROM item;','1','0|Constraint error','CHECK allows unknown; NOT NULL is needed to forbid missing n.','COUNT(n)|SUM(n)')),
 L('affinity','SQLite storage classes and type affinity',
 'SQLite attaches a storage class to each value; a column\'s affinity influences conversions but usually does not forbid other storage classes. NUMERIC affinity can turn digit text into an integer, while TEXT affinity stores a numeric input as text. CAST explicitly requests conversion and can have permissive behavior on malformed text. These rules are SQLite-specific; do not assume PostgreSQL or MySQL makes the same conversions. All fixtures start from a fresh in-memory database.',
 S('CREATE TABLE item(n ~TEXT~); INSERT INTO item VALUES(${n}); SELECT typeof(n) FROM item;','text','integer|real','TEXT affinity converts the supplied integer into text storage.','INTEGER|NUMERIC'),
 S('CREATE TABLE item(n ~NUMERIC~); INSERT INTO item VALUES(\'${n}\'); SELECT typeof(n) FROM item;','integer','text|real','NUMERIC affinity converts this well-formed integer text.','TEXT|BLOB'),
 S('CREATE TABLE item(n INTEGER); INSERT INTO item VALUES(\'${word}\'); SELECT ~typeof(n)~ FROM item;','text','integer|Constraint error','An ordinary INTEGER-affinity column can still hold nonnumeric text in SQLite.','n|length(n)'),
 S('SELECT CAST(\'bad\' AS ~INTEGER~);','0','Constraint error|NULL','SQLite converts this text to integer zero; a cast alone is not strict input validation.','TEXT|BLOB')),
 L('join-boundaries','Outer joins and predicate placement',
 'A join produces rows, possibly multiplying one left row into several matches. LEFT JOIN fills right columns with NULL when no match exists. A predicate in ON limits matching; the same predicate in WHERE can remove those preserved rows after the join. Count a non-null right key to count matches, since COUNT(*) also counts a null-extended row. Read qualifications and grouping carefully rather than treating a join as a dictionary lookup.',
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER,active INTEGER); INSERT INTO a VALUES(1); SELECT COUNT(*) FROM a LEFT JOIN b ON a.id=b.id ~AND b.active=1~;','1','0|2','The ON condition limits matches while retaining the unmatched left row.','WHERE b.active=1|WHERE b.id IS NOT NULL'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER,active INTEGER); INSERT INTO a VALUES(1); SELECT COUNT(*) FROM a LEFT JOIN b ON a.id=b.id ~WHERE b.active=1~;','0','1|2','The WHERE predicate rejects the null-extended row because its comparison is unknown.','WHERE b.id IS NULL|WHERE 1'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES(1); SELECT ~COUNT(b.id)~ FROM a LEFT JOIN b ON a.id=b.id;','0','1|NULL','Counting the right key ignores the NULL on the unmatched row.','COUNT(*)|COUNT(a.id)'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES(1); INSERT INTO b VALUES(1),(1); SELECT ~COUNT(*)~ FROM a JOIN b ON a.id=b.id;','2','1|0','Each matching right row contributes a result row.','COUNT(DISTINCT a.id)|0')),
 L('window-frames','Partitions, peers, and window frames',
 'Window functions calculate across related rows while keeping each result row. PARTITION BY separates independent groups. ORDER BY inside OVER controls window ordering but does not guarantee the final query order. ROWS defines a frame by physical row positions; provide a unique ordering key when ties would make positions ambiguous. A full-partition aggregate differs from a running frame. These lessons teach analytic SQL syntax, not an implementation of ranking algorithms.',
 S('WITH t(id,n) AS (VALUES(1,${n}),(2,${m})) SELECT SUM(n) OVER (~ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING~) FROM t ORDER BY id LIMIT 1;','${add}','${n}|${m}','The full frame includes both rows for each result.','ORDER BY id ROWS BETWEEN CURRENT ROW AND CURRENT ROW|ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW'),
 S('WITH t(id,n) AS (VALUES(1,${n}),(2,${m})) SELECT SUM(n) OVER (ORDER BY id ~ROWS BETWEEN CURRENT ROW AND CURRENT ROW~) FROM t ORDER BY id LIMIT 1;','${n}','${add}|${m}','A current-row-only frame contains exactly that row.','ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING|ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING'),
 S('WITH t(id,n) AS (VALUES(1,${n}),(2,${m})) SELECT ~LAG(n,1,0)~ OVER (ORDER BY id) FROM t ORDER BY id LIMIT 1;','0','${n}|${m}','The first row has no predecessor, so LAG returns its explicit fallback.','LEAD(n,1,0)|FIRST_VALUE(n)'),
 S('WITH t(id,tag,n) AS (VALUES(1,\'a\',${n}),(2,\'b\',${m})) SELECT SUM(n) OVER (~PARTITION BY tag~) FROM t ORDER BY id LIMIT 1;','${n}','${add}|0','Partitioning keeps the a and b totals separate before the outer limit selects the first row.','ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING|')),
 L('dates-sets','Date representations and compound queries',
 'SQLite has no dedicated date storage class; its date functions understand documented text and numeric representations. Modifiers change a supplied value, so explicit dates make tests reproducible. UNION removes duplicate rows, UNION ALL retains them, and EXCEPT removes rows present in the right query. Apply a final ORDER BY when result order matters. Compound query columns align by position; names do not join them together.',
 S('SELECT date(\'2024-02-28\',~\'+1 day\'~);','2024-02-29','2024-03-01|NULL','The explicit date lies in a leap year, so adding one day reaches February 29.','\'+2 days\'|\'-1 day\''),
 S('SELECT ~strftime(\'%Y\',\'2024-02-29\')~;','2024','02|29','The year format extracts text from the explicit date.','strftime(\'%m\',\'2024-02-29\')|strftime(\'%d\',\'2024-02-29\')'),
 S('SELECT COUNT(*) FROM (SELECT ${n} AS n ~UNION ALL~ SELECT ${n});','2','1|0','UNION ALL preserves duplicate result rows.','UNION|EXCEPT'),
 S('SELECT COUNT(*) FROM (SELECT ${n} AS n ~EXCEPT~ SELECT ${n});','0','1|2','EXCEPT removes the row present in the right query.','UNION|UNION ALL')),
 L('schema-changes','Transactional schema changes and returned writes',
 'A schema change alters contracts that application queries depend on. SQLite supports transactional DDL, so a migration can group related changes and roll back on failure. Use explicit column names when inserting to avoid depending on table order. RETURNING exposes values from changed rows in SQLite 3.35 and later, but does not imply the surrounding transaction is committed. Savepoints provide nested rollback boundaries; releasing one is not necessarily a top-level commit.',
 S('CREATE TABLE item(n INTEGER); INSERT INTO item VALUES(${n}); BEGIN; ALTER TABLE item ADD COLUMN label TEXT DEFAULT \'${word}\'; ~COMMIT~; SELECT label FROM item;','${word}','NULL|No such column','The committed added column supplies its default when existing rows are read.','ROLLBACK|SAVEPOINT pending'),
 S('CREATE TABLE item(n INTEGER); INSERT INTO item VALUES(${n}); BEGIN; UPDATE item SET n=n+1; ~ROLLBACK~; SELECT n FROM item;','${n}','${next}|0','Rollback discards the uncommitted update.','COMMIT|END'),
 S('CREATE TABLE item(id INTEGER PRIMARY KEY,n INTEGER); INSERT INTO item(n) VALUES(${n}) ~RETURNING n~;','${n}','1|No rows','RETURNING reads the inserted n from this write; no separate query is needed.','RETURNING id|'),
 S('CREATE TABLE item(n INTEGER); BEGIN; SAVEPOINT edit; INSERT INTO item VALUES(${n}); RELEASE edit; ~ROLLBACK~; SELECT COUNT(*) FROM item;','0','1|${n}','Releasing the inner savepoint does not commit the enclosing transaction.','COMMIT|END'))]
